import{z as s,x as A,o as e,c as d,q as l,j as t,D as n,d as B,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Blanchard–Kahn 条件","description":"","frontmatter":{"title":"Blanchard–Kahn 条件","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/blanchard-kahn.md","filePath":"econ/blanchard-kahn.md","lastUpdated":1791063341000}'),p={name:"econ/blanchard-kahn.md"};function h(c,a,m,D,C,u){const r=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="blanchard–kahn-条件" tabindex="-1">Blanchard–Kahn 条件 <a class="header-anchor" href="#blanchard–kahn-条件" aria-label="Permalink to &quot;Blanchard–Kahn 条件&quot;">​</a></h1><div class="epigraph"><p>跳变量的个数必须等于不稳定根的个数，有界理性预期解才唯一。</p><footer>—— Blanchard and Kahn, The Solution of Linear Difference Models under Rational Expectations, Econometrica 1980</footer></div><p><a href="/econ/log-linearization">上一课</a>交出线性 RE 系统。本课缺口是：<strong>何时有唯一有界解</strong>。根的计数替代显式横截，把爆炸路径丢掉。不重做对数线性的泰勒步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写成</p> \\[\\mathbb{E}_t Y_{t+1}=A Y_t+B\\varepsilon_{t+1}, \\]<p>\\(Y\\) 含预定与非预定（跳）变量。Blanchard–Kahn：不稳定特征值（模大于一）的个数等于跳变量个数时，存在唯一有界解；不稳定根太少则不定（太阳黑子可乘进来）；太多则无有界解。缺口是把「TVC 关掉爆炸」变成可检查的矩阵条件，而不是再写一条极限公式。</p><p><span class="marginnote">术语翻译：「预定变量」是昨天的资本、今天的存量，动不了；「跳变量」是通胀预期、资产价格这类可以一步跳到位的变量。BK 的计数，就是把「必须被钉住的」与「能负责跳的」数量对上号。</span></p><p><span class="marginnote">Sims 的 QZ 分解、Klein 的广义Schur，是 BK 在奇异系统上的数值实现。Uhlig 的未定系数是同一几何的代数写法。本课讲计数，不讲软件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把预定变量的初值当给定，跳变量的初值由「不能走不稳定流形」钉死。政策规则（泰勒系数、财政规则）进 \\(A\\)，从而改根。利率规则对通胀反应不足，常出现不定——Woodford 的决定性讨论是 BK 在 NK 里的应用，本课只留接口，不重写 NK 推导。太阳黑子：不稳定根不足时，外生鞅可以进解，波动不必来自基本面冲击。</p>',11)),(e(),t(i,null,{default:n(()=>[o(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E4%B8%8D%E7%A8%B3%E5%AE%9A%E6%A0%B9%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20CMP%5B%22%E5%AF%B9%E6%AF%94%E8%B7%B3%E5%8F%98%E9%87%8F%E4%B8%AA%E6%95%B0%22%5D%0A%20%20CMP%20--%3E%20UNIQ%5B%22%E7%9B%B8%E7%AD%89%3A%20%E5%94%AF%E4%B8%80%E6%9C%89%E7%95%8C%E8%A7%A3%22%5D%0A%20%20CMP%20--%3E%20IND%5B%22%E6%A0%B9%E5%B0%91%3A%20%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20CMP%20--%3E%20NOS%5B%22%E6%A0%B9%E5%A4%9A%3A%20%E6%97%A0%E6%9C%89%E7%95%8C%E8%A7%A3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"确定性 Ramsey 的鞍点：一维资本（预定）加一维消费（跳），一个稳定根一个不稳定根，正是 BK 的 \\(1=1\\)。随机线性化是同一张相图加噪声。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：Ramsey 里不稳定根 1 个、跳变量 1 个，\\(1=1\\)，唯一鞍点解。若政策规则改矩阵后不稳定根剩 0 个，跳变量反而无处可锚——这就是「不定」，太阳黑子可以乘进解里。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"机制是有界性当横截的线性替身。理性预期把未来跳变量写成今天信息的函数；若不把不稳定方向的载荷设为零，期望路径会爆。政策通过改 \\(A\\) 的特征值「创造」足够的不稳定根——看起来像把系统变不稳定，其实是给预期一个锚，让唯一有界路径存在。这与 Kydland–Prescott 的承诺不是同一句话，但都在说：规则改变方程，从而改变解的集合。",-1)),(e(),t(i,null,{default:n(()=>[o(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E4%BB%8A%E5%A4%A9%E5%86%B2%E5%87%BB%20%CE%B5%20%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20JUMP%5B%22%E8%B7%B3%E5%8F%98%E9%87%8F%EF%BC%88%E5%A6%82%E9%A2%84%E6%9C%9F%EF%BC%89%E9%A1%BB%E7%AB%8B%E5%8D%B3%E5%B0%B1%E4%BD%8D%22%5D%0A%20%20JUMP%20--%3E%20Q%7B%22%E4%B8%8D%E7%A8%B3%E5%AE%9A%E6%96%B9%E5%90%91%E4%B8%8A%E7%9A%84%E8%BD%BD%E8%8D%B7%E8%AE%BE%E4%B8%BA%E9%9B%B6%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20BOUNDED%5B%22%E6%8E%92%E9%99%A4%E7%88%86%E7%82%B8%E8%B7%AF%E5%BE%84%EF%BC%9A%E5%94%AF%E4%B8%80%E6%9C%89%E7%95%8C%E8%A7%A3%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20FREE%5B%22%E8%BD%BD%E8%8D%B7%E4%BB%BB%E6%84%8F%EF%BC%9A%E7%88%86%E7%82%B8%E6%88%96%E5%A4%AA%E9%98%B3%E9%BB%91%E5%AD%90%22%5D%0A%20%20RULE%5B%22%E6%94%BF%E7%AD%96%E8%A7%84%E5%88%99%E6%94%B9%20A%20%E7%9A%84%E7%89%B9%E5%BE%81%E5%80%BC%22%5D%20--%3E%20Q%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>不定不是「模型没写完」的同义反复：它是均衡多重。估计时若落在不定区，似然没有定义好的映射，后课贝叶斯会踩这个坑。</p><p><span class="marginnote">Blanchard and Kahn, <em>Econometrica</em> 48(5), 1980, 1305–1311。连续时间对应是鞍点稳定的特征值符号计数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理非线性局部不定、ZLB 下的分段线性、或全局太阳黑子。高阶扰动仍绕着同一确定性稳态，BK 的一阶解是中心。投影法可以走全局，不依赖本课计数，但大型 NK 仍以 BK 为默认。</p><p><span class="marginnote">常见误区：以为「政策让系统出现更多不稳定根」一定是坏事。BK 的语境正相反——多出来的不稳定根给预期一个锚，把爆炸路径筛掉；真正麻烦的是根太少（不定），那才允许太阳黑子波动。</span></p><p>后课默认：线性 DSGE 先查 BK；唯一解才能谈 IRF 与估计。下一课：在 BK 的一阶之外，扰动如何收回风险。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BK：不稳定根个数 = 跳变量个数 ⇒ 唯一有界线性 RE 解。</li><li>根少则不定，根多则无有界解。</li><li>政策规则通过改特征值决定解是否唯一。</li><li>出处：Blanchard and Kahn, <em>Econometrica</em> 1980。</li></ul>',8))])}const K=s(p,[["render",h]]);export{_ as __pageData,K as default};
